// usage: bun /tmp/amend.ts <edits.json> [--dry]
import { fold, toJSON } from '/Users/eryk.napierala/conductor/workspaces/werk/iqaluit/src/fold.ts'
import { readEvents } from '/Users/eryk.napierala/conductor/workspaces/werk/iqaluit/src/log.ts'
import { splitBlocks } from '/Users/eryk.napierala/conductor/workspaces/werk/iqaluit/web/diff.js'
import { spawnSync } from 'node:child_process'
import { readFileSync } from 'node:fs'
const edits = JSON.parse(readFileSync(process.argv[2], 'utf8'))
const dry = process.argv.includes('--dry')
const g: any = toJSON(fold(readEvents()))
const byId = new Map(g.nodes.map((n: any) => [n.id, n]))
for (const e of edits) {
  const n: any = byId.get(e.id); if (!n) { console.log(`!! ${e.id} missing`); continue }
  const args = ['src/cli.ts', 'propose', e.id]
  if (e.title) args.push('--title', e.title)
  if (e.why) args.push('--why', e.why)
  if (e.repl?.length) {
    const used = new Set<number>()
    const ops = splitBlocks(n.body ?? '').map((b: string) => {
      let nb = b
      e.repl.forEach(([o, r]: [string, string], i: number) => { if (nb.includes(o)) { nb = nb.split(o).join(r); used.add(i) } })
      return nb === '' ? { tag: 'removed', old: b } : { tag: 'elaborated', old: b, new: nb }
    })
    e.repl.forEach((r: any, i: number) => { if (!used.has(i)) console.log(`!! ${e.id}: no match for ${JSON.stringify(r[0]).slice(0, 80)}`) })
    args.push('--ops', JSON.stringify(ops))
  }
  if (dry) { console.log(`-- ${e.id} ok`); continue }
  const r = spawnSync('node', args, { encoding: 'utf8' })
  console.log(`-- ${e.id}: ${(r.stdout + r.stderr).split('\n')[0]}`)
}
